class MagicPotion {
  constructor(initialPower) {
    this.powerLevel = initialPower; // TODO: Make this private!
    this.secretIngredient = "Moonstone Dust"; // This should remain truly internal.
  }

  brew() {
    // TODO: Update private powerLevel
    this.powerLevel += 10;
    console.log(`Potion brewed! Power increased to ${this.powerLevel}`);
  }

  drink() {
    // TODO: Update private powerLevel, ensure it doesn't go below 0
    this.powerLevel -= 15;
    if (this.powerLevel < 0) {
      this.powerLevel = 0;
    }
    console.log(`Drank potion! Power is now ${this.powerLevel}`);
    return this.powerLevel;
  }

  getEffectDescription() {
    // TODO: Use private powerLevel for description
    if (this.powerLevel > 50) {
      return "Exudes powerful magical aura!";
    } else if (this.powerLevel > 0) {
      return "Glows faintly with magical energy.";
    } else {
      return "Seems inert.";
    }
  }
}

